def translate_fragment(value: str) -> str:
    """Translate app-owned copy while preserving source records and proper names.

    Standalone labels use exact lookup. Composite text uses one precompiled
    longest-first matcher, avoiding a regex pass for every dictionary phrase.
    """
    leading = value[:len(value) - len(value.lstrip())]
    trailing = value[len(value.rstrip()):]
    body = value.strip()
    if not body:
        return value
    exact = _FR_LOOKUP.get(body.casefold())
    if exact is not None:
        return leading + exact + trailing
    translated = _FR_PATTERN.sub(lambda match: _FR_LOOKUP.get(match.group(0).casefold(), match.group(0)), body)
    return leading + translated + trailing


def translate_html(html: str) -> str:
    soup = BeautifulSoup(html, "html.parser")
    for node in list(soup.find_all(string=True)):
        if isinstance(node, Comment) or node.parent.name in {"script", "style", "code", "pre"}:
            continue
        translated = translate_fragment(str(node))
        if translated != str(node):
            node.replace_with(NavigableString(translated))
    for element in soup.find_all(True):
        for attribute in ("placeholder", "aria-label", "aria-description", "title", "alt"):
            if element.has_attr(attribute) and isinstance(element.get(attribute), str):
                element[attribute] = translate_fragment(element.get(attribute))
    return str(soup)

