# Rebuild the lookup once more after the final status taxonomy additions.
_FR_LOOKUP = {key.casefold(): value for key, value in FR_UI.items()}
_FR_PHRASES = sorted(
    (key for key in FR_UI if key.endswith(":") or len(key) >= 8 or len(key.split()) >= 2),
    key=len, reverse=True,
)
_FR_PATTERN = re.compile(
    r"(?<![\w])(?:" + "|".join(re.escape(key) for key in _FR_PHRASES) + r")(?![\w])",
    flags=re.IGNORECASE,
) if _FR_PHRASES else re.compile(r"(?!)")
